void wifi_reconnect(void) {
    esp_wifi_disconnect();
    // No need to disable the watchdog, we will feed it.
    while (!wifi_connected()) {
        esp_wifi_connect();
        // Feed the watchdog to prevent reset during long reconnect attempts
        esp_task_wdt_reset(); 
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
    // Watchdog remains enabled and will be fed by other tasks or the idle task.
}
